"""Keep offline release text and About metadata derived from checked-in sources."""

import argparse
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]


def outputs():
    manifest = (ROOT / "mobile/pubspec.yaml").read_text(encoding="utf-8")
    version = re.search(r"^version: (\d+\.\d+\.\d+)\+(\d+)\s*$", manifest, re.M)
    if version is None:
        raise SystemExit("Expected a numeric release version and build in pubspec.yaml")
    name, build = version.groups()
    return {
        "mobile/lib/release_metadata.dart": (
            "// Generated by scripts/prepare_release.py from pubspec.yaml.\n"
            f"const pomaVersion = '{name}';\n"
            f"const pomaBuild = '{build}';\n"
            "const pomaOwner = 'Jyotirmay Singh';\n"
            "const pomaSupport = 'https://github.com/Jyotirmay-Singh/poma/issues';\n"
        ),
        "mobile/assets/legal/privacy.txt": (ROOT / "docs/PRIVACY_POLICY.md").read_text(encoding="utf-8"),
        "mobile/assets/legal/notices.txt": (ROOT / "THIRD_PARTY_NOTICES.md").read_text(encoding="utf-8"),
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    stale = []
    for relative, content in outputs().items():
        path = ROOT / relative
        if not path.is_file() or path.read_text(encoding="utf-8") != content:
            stale.append(relative)
            if not args.check:
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(content, encoding="utf-8", newline="\n")
    if args.check and stale:
        raise SystemExit("Run scripts/prepare_release.py; stale outputs: " + ", ".join(stale))
    print("Release metadata/legal assets " + ("verified" if args.check else "prepared"))


if __name__ == "__main__":
    main()
